UPDATE block_definitions SET styles='.stratum-form{display:grid;gap:var(--st-space-md)}.stratum-form-field{display:grid;gap:var(--st-space-xs)}.stratum-form input:not([type=checkbox]),.stratum-form textarea,.stratum-form select{width:100%;box-sizing:border-box;padding:var(--st-space-sm);color:var(--st-color-text);background:transparent;border:1px solid var(--st-color-border);border-radius:var(--st-radius-sm)}.stratum-form textarea{min-height:8rem;resize:vertical}.stratum-form button{justify-self:start}.stratum-form-honeypot{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important}.stratum-form-success{color:var(--st-color-text)}.stratum-form--disabled{padding:var(--st-space-md);border:1px solid var(--st-color-border);border-radius:var(--st-radius-sm);background:var(--st-color-bg-muted, #f9fafb);color:var(--st-color-text-muted, #6b7280)}', updated_at=unixepoch() WHERE namespace='core' AND name='form' AND version=1;
